records.command:
cat > .dip/tools/verify-dip-site.mjs <<'EOF'
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {readFileSync} from 'node:fs';
const origin='https://dip.vxu.me';
function get(path){return execFileSync('curl',['--fail','--silent','--show-error','--max-time','30',origin+path]);}
const html=get('/').toString();
assert(html.includes('Your session ends.') && html.includes('npm install -g github:vxu-labs/dip'));
assert(html.includes('https://dip.vxu.me/'));
for(const path of ['/style.css','/script.js','/assets/dashboard.png','/assets/favicon.svg','/robots.txt','/sitemap.xml']){
 assert.deepEqual(get(path),readFileSync('sites/dip-public/dist'+path),path+' differs from deployed source');
}
console.log('PASS: public HTTPS page, expected DIP content and all six deployed assets match local source.');
EOF
python3 - <<'PY'
import json
p='.dip/config.json';d=json.load(open(p));d.setdefault('verification',{})['dip-public-site']={'command':['node','.dip/tools/verify-dip-site.mjs'],'timeoutMs':120000};open(p,'w').write(json.dumps(d,indent=2)+'\n')
PY

